style.css:
@-moz-document domain("userstyles.org") {
/* Fondo general oscuro estilo ciudad de noche */
  body {
    background-color: #1c1c1e !important;
    color: #f0f0f5 !important;
    font-family: 'Helvetica Neue', Arial, sans-serif !important;
  }

  /* Encabezado estilo moderno con neón */
  header, .header, .navbar {
    background-color: #000000 !important;
    border-bottom: 2px solid #f1c40f !important;
    box-shadow: 0 0 10px #f1c40f88;
  }

  /* Botones con estilo amarillo taxi */
  button, .button, input[type="submit"] {
    background-color: #f1c40f !important;
    color: #000 !important;
    border: none !important;
    border-radius: 6px !important;
    font-weight: bold;
    transition: all 0.3s ease-in-out;
  }

  button:hover, .button:hover, input[type="submit"]:hover {
    background-color: #ffd700 !important;
    box-shadow: 0 0 5px #f1c40f;
    cursor: pointer;
  }

  /* Enlaces con estilo neón blanco */
  a {
    color: #ffffff !important;
    text-decoration: none;
    border-bottom: 1px dashed #aaa;
  }

  a:hover {
    color: #f1c40f !important;
    border-bottom: 1px solid #f1c40f;
  }

  /* Caja de código estilo asfalto con texto claro */
  pre, code, textarea {
    background-color: #2e2e33 !important;
    color: #e0e0e0 !important;
    border-radius: 4px;
    padding: 10px;
    font-family: monospace;
  }

  /* Estilo del área de creación */
  #editor, .ace_editor {
    background-color: #1c1c1e !important;
    color: #ffffff !important;
  }

  /* Pie de página minimalista */
  footer {
    background-color: #111 !important;
    color: #888 !important;
    border-top: 1px solid #333;
  }

  /* Títulos y cabeceras */
  h1, h2, h3, h4, h5 {
    color: #ffffff !important;
    font-family: 'Franklin Gothic Medium', 'Arial Narrow', Arial, sans-serif;
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  /* Bordes y elementos secundarios */
  .panel, .box, .card, .container {
    background-color: #2a2a2d !important;
    border: 1px solid #444 !important;
    border-radius: 8px;
    padding: 10px;
  }
}
